41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
54	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
55	
56	const quote = (step: QuoteStep): StepResult => {
57	  const policyBasePremium = step.items.reduce(
58	    (sum, item) => sum + BASE_PREMIUMS[item.type],
59	    0,
60	  );
61	  return {
62	    premium: roundPremiumInMHPCOFavour(
63	      policyBasePremium +
64	        policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE +
65	        PROCESSING_FEE,
66	    ),
67	  };
68	};
69	
70	const runStep = (step: Step): StepResult => {
71	  if (step.op === "quote") return quote(step);
72	  throw new Error(`Unsupported step: ${step.op}`);
73	};
74	
75	export const runScenario = (scenario: Scenario): ScenarioResult => ({
76	  results: scenario.steps.map(runStep),
77	});
